/* worldLand.js - the world's coastlines for the Develop map.
   Generated once from Natural Earth 1:110m land (public domain, via the
   world-atlas package); equirectangular, 1000 x 500, latitude 84 to -58
   (Antarctica left off). Land that crosses the 180° line is unwrapped and
   drawn on both edges. Nothing here needs editing. */

export const WORLD_W = 1000;
export const WORLD_H = 500;
const LAT_MAX = 84;
const LAT_MIN = -58;

/* longitude / latitude -> a point on the 1000 x 500 map */
export const project = (lon, lat) => ({
  x: ((lon + 180) / 360) * WORLD_W,
  y: ((LAT_MAX - lat) / (LAT_MAX - LAT_MIN)) * WORLD_H,
});

